/**
 * Wave-N test suite — cross-impl byte-equivalence with the
 * canonical Rust verifier at the canonical verifier, the Go port at
 * `tools/auditproof-verifier-go/wave_n.go`, and the Python port at
 * the Python SDK.
 *
 * **Forever-Standard discipline:** every test here pins a
 * cryptographic-attestation contract. Any divergence from the Rust reference
 * vectors is a P0 finding.
 *
 * Cross-impl reference vectors (generated by
 * `cargo run --package nanorix-rzl --example gen_wave_n_vectors`) are
 * hard-coded in `Cross-impl reference vectors` tests below. They MUST also
 * match the Go + Python test constants verbatim — these constants are the
 * 4-language byte-equivalence anchor.
 */
import { describe, it, expect } from "vitest";

import {
  GENESIS_SHA512_HEX,
  PARENT_PROOF_MAX_DEPTH,
  PATTERN_TAGS_WIRE,
  WaveNVerifyError,
  merklePairHash,
  merkleRootSha512NullSeparated,
  computeRecordReceiptsMerkleRoot,
  computeParentProofsMerkleRoot,
  buildMerkleInclusionProof,
  verifyMerkleInclusionProof,
  computeActivityRoot,
  computeRecordChainHash,
  computeStep8Base,
  computeStep8Amended,
  detectParentProofCycle,
  enforceDepthCap,
  verifyRecordReceipt,
  verifyFullAuditProof,
  type WaveNRecordReceipt,
  type WaveNParentProofLink,
} from "../src/verifier/wave_n.js";
import { GENESIS_HASH } from "../src/verifier/index.js";

const WAVE_N_TIMESTAMP = "2026-05-12T00:00:00Z";
const WAVE_N_CAPSULE_ID = "cap_wave_n_fixture";

const subtle = (globalThis as unknown as { crypto: Crypto }).crypto.subtle;

async function ed25519Supported(): Promise<boolean> {
  try {
    await subtle.generateKey({ name: "Ed25519" }, false, ["sign", "verify"]);
    return true;
  } catch {
    return false;
  }
}

async function sha512Hex(data: Uint8Array): Promise<string> {
  const digest = await subtle.digest("SHA-512", data.buffer as ArrayBuffer);
  const bytes = new Uint8Array(digest);
  let out = "";
  for (let i = 0; i < bytes.length; i++) {
    out += bytes[i].toString(16).padStart(2, "0");
  }
  return out;
}

function bytesToBase64(buf: ArrayBuffer | Uint8Array): string {
  const bytes = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
  return Buffer.from(bytes).toString("base64");
}

// Pre-Wave-N legacy step hash — for Forever-Standard cross-check.
async function legacyStepHash(
  prev: string,
  subsystem: string,
  method: string,
  timestamp: string,
): Promise<string> {
  const enc = new TextEncoder();
  const NULL = new Uint8Array([0]);
  const parts = [
    enc.encode(prev),
    NULL,
    enc.encode(subsystem),
    NULL,
    enc.encode("destroy"),
    NULL,
    enc.encode(method),
    NULL,
    enc.encode(timestamp),
  ];
  const total = parts.reduce((acc, p) => acc + p.length, 0);
  const buf = new Uint8Array(total);
  let off = 0;
  for (const p of parts) {
    buf.set(p, off);
    off += p.length;
  }
  return sha512Hex(buf);
}

